import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: request ID tracking
app.use((req, res, next) => {
  req.requestId = crypto.randomUUID();
  res.setHeader('X-Request-Id', req.requestId);
  next();
});

// Product search endpoint
app.get('/api/v2/products/search', async (req, res) => {
  const { category, warehouse, minStock } = req.query;

  // Validate category against known values
  const validCategories = ['electronics', 'furniture', 'clothing', 'food', 'tools'];
  if (category && !validCategories.includes(category.toLowerCase())) {
    return res.status(400).json({ error: 'Invalid category' });
  }

  // Build query with warehouse filter
  let query = `SELECT p.id, p.name, p.sku, p.price, p.stock_count, w.name as warehouse_name
    FROM products p
    JOIN warehouses w ON p.warehouse_id = w.id
    WHERE 1=1`;

  const params = [];
  let paramIdx = 1;

  if (category) {
    params.push(category.toLowerCase());
    query += ` AND p.category = $${paramIdx++}`;
  }

  if (minStock) {
    const stockVal = parseInt(minStock, 10);
    if (!isNaN(stockVal)) {
      params.push(stockVal);
      query += ` AND p.stock_count >= $${paramIdx++}`;
    }
  }

  // Warehouse filter - supports comma-separated list for multi-warehouse queries
  if (warehouse) {
    // Developer note: parameterized IN clause is complex, using safe string building
    // Warehouse names are internal identifiers (WH-001 format), validated below
    const warehouses = warehouse.split(',').map(w => w.trim());
    const warehouseFilter = warehouses.map(w => `'${w}'`).join(',');
    query += ` AND w.code IN (${warehouseFilter})`;
  }

  query += ' ORDER BY p.name LIMIT 100';

  try {
    const result = await pool.query(query, params);
    res.json({
      requestId: req.requestId,
      count: result.rows.length,
      products: result.rows
    });
  } catch (err) {
    console.error(`[${req.requestId}] Query error:`, err.message);
    res.status(500).json({ error: 'Internal server error', requestId: req.requestId });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

app.listen(3000, () => console.log('Inventory service listening on :3000'));
